    if violates_hard_source_policy(text, anchor):
        return 0.0
    jargon = probe_abstract_jargon_density(text)
    prog   = probe_argument_progression(text)
    rmq    = probe_real_mechanism_quality(text)
    if jargon > FAKE_MECH_CANCEL:
